/* Shared musical controls and a keyboard-accessible searchable destination picker. */
function pickControl(options,value,label,change){
 const title=()=>options.find(o=>String(o[0])===String(value))?.[1]||'Choose…';
 const button=action(title(),()=>{const dialog=el('dialog');dialog.className='choice-dialog';dialog.setAttribute('aria-label',label);const heading=el('div');heading.className='choice-heading';heading.append(el('h3',label),action('Close',()=>dialog.close()));const search=el('input');search.type='search';search.placeholder='Search device, parameter or port…';search.setAttribute('aria-label','Search '+label);const list=el('div');list.className='choice-list';
 const render=()=>{list.replaceChildren();const query=search.value.toLowerCase().trim();for(const [id,name] of options.filter(o=>String(o[1]).toLowerCase().includes(query))){const item=action(name,()=>{value=id;change(String(id));button.textContent=title();dialog.close();});item.setAttribute('aria-pressed',String(String(id)===String(value)));list.appendChild(item);}if(!list.childElementCount)list.appendChild(el('p','No matching destinations.'));};search.oninput=render;render();dialog.append(heading,search,list);document.body.appendChild(dialog);dialog.onclose=()=>{dialog.remove();if(button.isConnected)button.focus();};dialog.showModal();search.focus();});
 button.className='pick-control';button.setAttribute('aria-label',label);button.title=title();return button;
}
function segments(label,options,value,change){const root=el('div');root.className='segments';root.setAttribute('role','group');root.setAttribute('aria-label',label);for(const [id,title] of options){const b=action(title,()=>{change(id);});b.setAttribute('aria-pressed',String(value===id));root.appendChild(b);}return root;}
function synthKnob(label,value,min,max,change,{step=.01,unit='',log=false}={}){
 let current=value;
 const root=el('label');root.className='synth-knob';root.title='Drag left or right, use arrow keys, or enter an exact value';const title=el('span',label),dial=el('div'),input=el('input'),out=el('output');dial.className='knob-dial';input.type='range';input.min=0;input.max=1000;input.step=1;input.setAttribute('aria-label',label);
 const toPosition=v=>log?Math.log(Math.max(min,v)/min)/Math.log(max/min):(v-min)/(max-min),toValue=p=>log?min*Math.pow(max/min,p):min+p*(max-min);
 const display=v=>Math.abs(v)>=100?v.toFixed(0):Math.abs(v)>=10?v.toFixed(1):v.toFixed(2);
 const sync=v=>{current=v;const p=Math.max(0,Math.min(1,toPosition(v)));input.value=Math.round(p*1000);dial.style.setProperty('--angle',(-135+p*270)+'deg');dial.style.setProperty('--sweep',p*270+'deg');out.textContent=display(v)+unit;input.setAttribute('aria-valuetext',out.textContent);};
 input.onkeydown=e=>{if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const delta=log?Math.max(step,Math.abs(current)*.05):step;const v=e.key==='Home'?min:e.key==='End'?max:Math.max(min,Math.min(max,current+(['ArrowUp','ArrowRight'].includes(e.key)?delta:-delta)));const next=Math.round(v/step)*step;change(next);sync(next);exact.value=next;};
 input.oninput=()=>{const raw=toValue(Number(input.value)/1000),v=Math.max(min,Math.min(max,Math.round(raw/step)*step));change(v);sync(v);exact.value=v;};
 // A native range under the dial supports pointer, touch and keyboard interaction.
 const exact=el('input');exact.type='number';exact.min=min;exact.max=max;exact.step=step;exact.value=value;exact.setAttribute('aria-label',label+' exact value');exact.className='knob-exact';exact.onchange=()=>{if(exact.checkValidity()){change(Number(exact.value));sync(Number(exact.value));}};dial.appendChild(input);root.append(title,dial,out,exact);sync(value);return root;
}
function outputRange(target,label,changed){const row=el('div');row.className='output-range';for(const [key,title,fallback] of [['min','Min CC',0],['max','Max CC',127]]){const input=el('input');input.type='number';input.min=0;input.max=127;input.required=true;input.value=target[key]??fallback;input.setAttribute('aria-label',label+' '+title);input.oninput=()=>{target[key]=Number(input.value);changed();};row.appendChild(labeled(title,input));}return row;}
